"""Render a C header from Zig-reflected function signatures; fail on drift."""
import json
from pathlib import Path
import sys

root = Path(__file__).resolve().parent
raw = sys.stdin.buffer.read()
contract = json.loads(raw)
lines = [
    "/* Generated by just contract::client-generate; do not edit. */",
    "#ifndef TRANSIT_CLIENT_H", "#define TRANSIT_CLIENT_H",
    "#include <stddef.h>", "#include <stdint.h>",
    '#ifdef __cplusplus\nextern "C" {\n#endif',
    f'#define TRANSIT_CLIENT_ABI_VERSION {contract["version"]}u',
]
for name in ("client", "operation", "buffer"):
    lines.append(f"typedef struct transit_{name} transit_{name};")
for group in ("statuses", "kinds"):
    prefix = "STATUS" if group == "statuses" else "KIND"
    for name, value in contract[group].items():
        lines.append(f"#define TRANSIT_{prefix}_{name.upper()} {value}u")
for function in contract["functions"]:
    parameters = ", ".join(f"{value} arg{i}" for i, value in enumerate(function["parameters"])) or "void"
    lines.append(f'{function["result"]} {function["name"]}({parameters});')
lines += ["#ifdef __cplusplus\n}\n#endif", "#endif", ""]
outputs = {
    root / "include/transit_client.h": "\n".join(lines).encode(),
    root / "abi-v1.json": raw,
}
for path, content in outputs.items():
    if "--write" in sys.argv:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(content)
    elif not path.exists() or path.read_bytes() != content:
        raise SystemExit("Client ABI drift: run just contract::client-generate and review")
print("Client ABI declarations match the Zig exports.")
